), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"triathlon_m_8w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "triathlon_m_8w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "triathlon_m_8w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "triathlon_m_8w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'triathlon_m_8w_name', 'triathlon_m_8w_description', 'triathlon_m_8w_objective', 8, 'intermediate', 'training', 4, true, '{"name": {"fr": "Triathlon M (olympique) en aéro", "en": "Olympic-distance triathlon in aero", "es": "Triatlón olímpico en aero", "it": "Triathlon olimpico in aero", "de": "Olympische Distanz in Aero", "nl": "Olympische triatlon in aero", "pt": "Triatlo olímpico em aero", "ja": "オリンピックディスタンス・トライアスロン（エアロ）", "tr": "Aero''da olimpik mesafe triatlon"}, "objective": {"fr": "Tenir la position TT à l''allure triathlon (85-90 % FTP) pendant l''équivalent d''un vélo de 40 km, soit 60 minutes d''affilée.", "en": "Hold the TT position at triathlon pace (85-90% FTP) for the length of a 40 km bike leg, i.e. 60 minutes in a row.", "es": "Mantener la posición TT a ritmo de triatlón (85-90 % FTP) lo que dura una bici de 40 km, es decir 60 minutos seguidos.", "it": "Tenere la posizione TT al ritmo triathlon (85-90 % FTP) per la durata di una frazione bici di 40 km, cioè 60 minuti di fila.", "de": "Die TT-Position im Triathlontempo (85-90 % FTP) über die Dauer einer 40-km-Radstrecke halten, also 60 Minuten am Stück.", "nl": "De TT-houding op triatlontempo (85-90 % FTP) vasthouden zo lang als een fietsdeel van 40 km, dus 60 minuten aan één stuk.", "pt": "Manter a posição TT no ritmo do triatlo (85-90 % FTP) pelo tempo de uma bike de 40 km, ou seja 60 minutos seguidos.", "ja": "トライアスロンペース（85〜90 % FTP）で40 kmのバイク相当、60分連続でTTポジションを保つ。", "tr": "40 km''lik bisiklet etabı süresince, yani aralıksız 60 dakika triatlon temposunda (%85-90 FTP) TT pozisyonunu koru."}, "description": {"fr": "8 semaines pour le vélo d''un triathlon M (40 km). Allure triathlon en TT de 2×15'' à 60'' d''affilée, sweet spot et seuil, une séance de PMA et une sortie longue TT jusqu''à 2 h 35. Semaine 8 : affûtage avant la course.", "en": "8 weeks for the bike leg of an Olympic-distance triathlon (40 km). Triathlon pace in TT from 2×15'' to 60'' in a row, sweet spot and threshold, one VO2max session and one long TT ride up to 2 h 35. Week 8: taper before the race.", "es": "8 semanas para la bici de un triatlón olímpico (40 km). Ritmo de triatlón en TT de 2×15'' a 60'' seguidos, sweet spot y umbral, una sesión de VO2max y una salida larga TT hasta 2 h 35. Semana 8: puesta a punto antes de la carrera.", "it": "8 settimane per la frazione bici di un triathlon olimpico (40 km). Ritmo triathlon in TT da 2×15'' a 60'' di fila, sweet spot e soglia, una sessione di VO2max e un''uscita lunga TT fino a 2 h 35. Settimana 8: scarico prima della gara.", "de": "8 Wochen für die Radstrecke einer olympischen Distanz (40 km). Triathlontempo in TT von 2×15'' bis 60'' am Stück, Sweet Spot und Schwelle, eine VO2max-Einheit und eine lange TT-Fahrt bis 2 h 35. Woche 8: Tapering vor dem Rennen.", "nl": "8 weken voor het fietsdeel van een olympische triatlon (40 km). Triatlontempo in TT van 2×15'' tot 60'' aan één stuk, sweet spot en drempel, één VO2max-sessie en één lange TT-rit tot 2 u 35. Week 8: taperen voor de wedstrijd.", "pt": "8 semanas para a bike de um triatlo olímpico (40 km). Ritmo de triatlo em TT de 2×15'' a 60'' seguidos, sweet spot e limiar, uma sessão de VO2max e um treino longo TT até 2 h 35. Semana 8: polimento antes da prova.", "ja": "オリンピックディスタンス（40 km）のバイクのための8週間。TTでのトライアスロンペースは2×15''から60''連続まで、スイートスポットと閾値、VO2maxセッション1回、最大2時間35分のロングTTライド。8週目はレース前の調整。", "tr": "Olimpik mesafe triatlonun bisiklet etabı (40 km) için 8 hafta. TT''de triatlon temposu 2×15''''den aralıksız 60''''ye, sweet spot ve eşik, bir VO2max seansı ve 2 sa 35''e kadar uzun TT sürüşü. 8. hafta: yarış öncesi toparlanma."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'triathlon_m_8w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'triathlon_m_8w_w1s1_name'), (1, 2, 'triathlon_m_8w_w1s2_name'), (1, 3, 'triathlon_m_8w_w1s3_name'), (1, 4, 'triathlon_m_8w_w1s4_name'), (2, 1, 'triathlon_m_8w_w2s1_name'), (2, 2, 'triathlon_m_8w_w2s2_name'), (2, 3, 'triathlon_m_8w_w2s3_name'), (2, 4, 'triathlon_m_8w_w2s4_name'), (3, 1, 'triathlon_m_8w_w3s1_name'), (3, 2, 'triathlon_m_8w_w3s2_name'), (3, 3, 'triathlon_m_8w_w3s3_name'), (3, 4, 'triathlon_m_8w_w3s4_name'), (4, 1, 'triathlon_m_8w_w4s1_name'), (4, 2, 'triathlon_m_8w_w4s2_name'), (4, 3, 'triathlon_m_8w_w4s3_name'), (5, 1, 'triathlon_m_8w_w5s1_name'), (5, 2, 'triathlon_m_8w_w5s2_name'), (5, 3, 'triathlon_m_8w_w5s3_name'), (5, 4, 'triathlon_m_8w_w5s4_name'), (6, 1, 'triathlon_m_8w_w6s1_name'), (6, 2, 'triathlon_m_8w_w6s2_name'), (6, 3, 'triathlon_m_8w_w6s3_name'), (6, 4, 'triathlon_m_8w_w6s4_name'), (7, 1, 'triathlon_m_8w_w7s1_name'), (7, 2, 'triathlon_m_8w_w7s2_name'), (7, 3, 'triathlon_m_8w_w7s3_name'), (7, 4, 'triathlon_m_8w_w7s4_name'), (8, 1, 'triathlon_m_8w_w8s1_name'), (8, 2, 'triathlon_m_8w_w8s2_name'), (8, 3, 'triathlon_m_8w_w8s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'triathlon_m_8w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
